    const result = mri(["-a", "01"], {
      alias: { arg: "a" },
      string: ["arg"],
    });
    expect(result.arg).toBe("01");
    expect(result.a).toBe("01");
    expect(typeof result.arg).toBe("string");
    expect(typeof result.a).toBe("string");
  });

  test("no default, no string option - number coercion still works", () => {
    const result = mri(["-a", "42"], {
      alias: { arg: "a" },
    });
    expect(result.arg).toBe(42);
    expect(result.a).toBe(42);
    expect(typeof result.arg).toBe("number");
    expect(typeof result.a).toBe("number");
  });

  test("explicit string option overrides default type inference", () => {
    const result = mri(["-a", "42"], {
      alias: { arg: "a" },
      default: { arg: "hello" },
      string: ["a"],
    });
    expect(result.arg).toBe("42");
    expect(result.a).toBe("42");
    expect(typeof result.arg).toBe("string");
    expect(typeof result.a).toBe("string");
  });

  test("empty string default preserves string type", () => {
    const result = mri(["-a", "test"], {
      alias: { arg: "a" },
      default: { arg: "" },
    });
    expect(result.arg).toBe("test");
    expect(result.a).toBe("test");
    expect(typeof result.arg).toBe("string");
    expect(typeof result.a).toBe("string");
  });

  test("long flag with alias and string default", () => {
    const result = mri(["--arg", "00123"], {
      alias: { arg: "a" },
      default: { arg: "default" },
    });
    expect(result.arg).toBe("00123");
    expect(result.a).toBe("00123");
    expect(typeof result.arg).toBe("string");
    expect(typeof result.a).toBe("string");
  });

  test("multiple defaults with mixed types", () => {
    const result = mri(["-n", "007"], {
      alias: { name: "n", flag: "f" },
      default: { name: "default", flag: true },
    });
    expect(result.name).toBe("007");
    expect(result.n).toBe("007");
    expect(typeof result.name).toBe("string");
    expect(typeof result.n).toBe("string");
    expect(result.flag).toBe(true);
    expect(result.f).toBe(true);
    expect(typeof result.flag).toBe("boolean");
    expect(typeof result.f).toBe("boolean");
  });

  test("boundary: very long leading zeros", () => {
    const result = mri(["-a", "00000001"], {
      alias: { arg: "a" },
      default: { arg: "" },
    });
    expect(result.arg).toBe("00000001");
    expect(result.a).toBe("00000001");
    expect(typeof result.arg).toBe("string");
    expect(typeof result.a).toBe("string");
  });

  test("boundary: negative number as string default", () => {
    const result = mri(["-a", "-001"], {
      alias: { arg: "a" },
      default: { arg: "0" },
    });
    expect(result.arg).toBe("-001");
    expect(result.a).toBe("-001");
    expect(typeof result.arg).toBe("string");
    expect(typeof result.a).toBe("string");
  });

  test("boundary: no argument provided uses default", () => {
    const result = mri([], {
      alias: { arg: "a" },
      default: { arg: "01" },
    });
    expect(result.arg).toBe("01");
    expect(result.a).toBe("01");
    expect(typeof result.arg).toBe("string");
    expect(typeof result.a).toBe("string");
  });
});

